class _PigeonCodec extends StandardMessageCodec {
  const _PigeonCodec();
  @override
  void writeValue(WriteBuffer buffer, Object? value) {
    if (value is int) {
      buffer.putUint8(4);
      buffer.putInt64(value);
    }    else if (value is FileMeta) {
      buffer.putUint8(129);
      writeValue(buffer, value.encode());
    }    else if (value is PdfInfo) {
      buffer.putUint8(130);
      writeValue(buffer, value.encode());
    }    else if (value is PdfMetadata) {
      buffer.putUint8(131);
      writeValue(buffer, value.encode());
    }    else if (value is DuplicateGroup) {
      buffer.putUint8(132);
      writeValue(buffer, value.encode());
    }    else if (value is StorageEntry) {
      buffer.putUint8(133);
      writeValue(buffer, value.encode());
    }    else if (value is ImageFacts) {
      buffer.putUint8(134);
      writeValue(buffer, value.encode());
    }    else if (value is BarcodeResult) {
      buffer.putUint8(135);
      writeValue(buffer, value.encode());
    }    else if (value is OcrBlock) {
      buffer.putUint8(136);
      writeValue(buffer, value.encode());
    }    else if (value is FormField) {
      buffer.putUint8(137);
      writeValue(buffer, value.encode());
    }    else if (value is FormFieldValue) {
      buffer.putUint8(138);
      writeValue(buffer, value.encode());
    }    else if (value is PageText) {
      buffer.putUint8(139);
      writeValue(buffer, value.encode());
    }    else if (value is InkStroke) {
      buffer.putUint8(140);
      writeValue(buffer, value.encode());
    }    else if (value is RectMark) {
      buffer.putUint8(141);
      writeValue(buffer, value.encode());
    }    else if (value is RedactionMark) {
      buffer.putUint8(142);
      writeValue(buffer, value.encode());
    } else {
      super.writeValue(buffer, value);
    }
  }

  @override
  Object? readValueOfType(int type, ReadBuffer buffer) {
    switch (type) {
      case 129:
        return FileMeta.decode(readValue(buffer)!);
      case 130:
        return PdfInfo.decode(readValue(buffer)!);
      case 131:
        return PdfMetadata.decode(readValue(buffer)!);
      case 132:
        return DuplicateGroup.decode(readValue(buffer)!);
      case 133:
        return StorageEntry.decode(readValue(buffer)!);
      case 134:
        return ImageFacts.decode(readValue(buffer)!);
      case 135:
        return BarcodeResult.decode(readValue(buffer)!);
      case 136:
        return OcrBlock.decode(readValue(buffer)!);
      case 137:
        return FormField.decode(readValue(buffer)!);
      case 138:
        return FormFieldValue.decode(readValue(buffer)!);
      case 139:
        return PageText.decode(readValue(buffer)!);
      case 140:
        return InkStroke.decode(readValue(buffer)!);
      case 141:
        return RectMark.decode(readValue(buffer)!);
      case 142:
        return RedactionMark.decode(readValue(buffer)!);
      default:
        return super.readValueOfType(type, buffer);
    }
  }
}

